            if (q !== (i % 10)) begin
                errors = errors + 1;
            end
        end

        // Test 3: Asynchronous/Synchronous Reset injection mid-count
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 4'b0000) begin
            errors = errors + 1;
        end

        // Deassert reset and check resumption from 0
        @(posedge clk);
        reset = 0;
        #1;
        if (q !== 4'b0001) begin // At posedge after reset=0, q should be 0+1 = 1
            errors = errors + 1;
        end

        // Final Result Display
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
